quests[10468] = { id = 10468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur des Weisen", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, {name}. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", sourceObjectiveStatus = "unverified-source-field" }
